package slug

import "testing"

func TestSlug(t *testing.T) {
	if got := Slug("Hello World"); got != "hello-world" {
		t.Fatalf("got %q", got)
	}
	if got := Slug("  a  b "); got != "a-b" {
		t.Fatalf("got %q", got)
	}
	if got := Slug(""); got != "" {
		t.Fatalf("got %q", got)
	}
}

